/** Fictional v0.1 backups generated by scripts/dev/generate-v01-fixtures.mjs. */
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { ROOT } from '../../scripts/lib/content.mjs';

const DIR = join(ROOT, 'tests', 'fixtures', 'v0.1');

/** @returns {{ name: string, text: string }[]} every v0.1 backup file */
export function v01Backups() {
  return readdirSync(DIR).filter((f) => f.endsWith('.json')).map((name) => ({ name, text: readFileSync(join(DIR, name), 'utf8') }));
}

